// Generated by npm run content:legacy. Full tokens remain in each chapter's dist/cues.json.
const raw = {"seed-1":[{"id":"c0001","kind":"content","startMs":0,"endMs":1683,"text":"Pip is a little rabbit.","translation":"Pip 是一只小兔子。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":1683,"endMs":3885,"text":"He finds a seed in the garden.","translation":"他在花园里找到一颗种子。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":3885,"endMs":6047,"text":"He puts the seed in the soil.","translation":"他把种子放进泥土里。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":6047,"endMs":8848,"text":"The little seed needs water and sunshine.","translation":"小种子需要水和阳光。","reviewStatus":"needs_review"}],"seed-2":[{"id":"c0001","kind":"content","startMs":0,"endMs":2462,"text":"Pip gives the seed water every day.","translation":"Pip 每天都给种子浇水。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":2462,"endMs":5299,"text":"One morning, he sees a green leaf.","translation":"一天早晨，他看见了一片绿叶。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":5299,"endMs":7735,"text":"A yellow flower opens in the sun.","translation":"一朵黄色的小花在阳光下绽放。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":7735,"endMs":10176,"text":"Pip smiles at his new little friend.","translation":"Pip 对他的新朋友笑了。","reviewStatus":"needs_review"}],"fox-1":[{"id":"c0001","kind":"content","startMs":0,"endMs":2642,"text":"A little fox walks through the forest.","translation":"一只小狐狸走过森林。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":2642,"endMs":5000,"text":"He sees a bright star above him.","translation":"他看见头顶有一颗明亮的星星。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":5000,"endMs":7312,"text":"The star looks like a tiny lamp.","translation":"星星看起来像一盏小灯。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":7312,"endMs":9630,"text":"He wants to bring the star home.","translation":"他想把星星带回家。","reviewStatus":"needs_review"}],"fox-2":[{"id":"c0001","kind":"content","startMs":0,"endMs":2488,"text":"The fox climbs a tall green hill.","translation":"小狐狸爬上一座绿色的高山丘。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":2488,"endMs":4600,"text":"The star is still far away.","translation":"星星依然很遥远。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":4600,"endMs":7067,"text":"He sits down and watches the sky.","translation":"他坐下来，望着天空。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":7067,"endMs":9736,"text":"His bright friend follows him all night.","translation":"他明亮的朋友整晚都陪着他。","reviewStatus":"needs_review"}],"bear-1":[{"id":"c0001","kind":"content","startMs":0,"endMs":2310,"text":"Bear has a big picnic basket.","translation":"小熊有一个大大的野餐篮。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":2310,"endMs":4696,"text":"He puts apples and bread inside.","translation":"他把苹果和面包放进去。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":4696,"endMs":6911,"text":"He takes a blanket to the park.","translation":"他带着一条毯子来到公园。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":6911,"endMs":9163,"text":"His friends are coming for lunch.","translation":"他的朋友们要来一起吃午饭。","reviewStatus":"needs_review"}],"bear-2":[{"id":"c0001","kind":"content","startMs":0,"endMs":2589,"text":"Rabbit brings a cup of sweet juice.","translation":"小兔带来一杯甜甜的果汁。","reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":2589,"endMs":5200,"text":"Fox brings three little red cups.","translation":"小狐狸带来三个红色的小杯子。","reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":5200,"endMs":7356,"text":"They share the food under a tree.","translation":"他们在树下分享食物。","reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":7356,"endMs":10155,"text":"Everything tastes better with good friends.","translation":"和好朋友一起，什么都更好吃了。","reviewStatus":"needs_review"}],"oz-1":[{"id":"c0001","kind":"heading","startMs":20360,"endMs":22200,"text":"Chapter I. The Cyclone.","translation":null,"reviewStatus":"needs_review"},{"id":"c0002","kind":"content","startMs":23400,"endMs":31560,"text":"Dorothy lived in the midst of the great Kansas prairies, with Uncle Henry, who was a farmer, and Aunt Em, who was the farmer's wife.","translation":null,"reviewStatus":"needs_review"},{"id":"c0003","kind":"content","startMs":32100,"endMs":36880,"text":"Their house was small, for the lumber to build it had to be carried by wagon many miles.","translation":null,"reviewStatus":"needs_review"},{"id":"c0004","kind":"content","startMs":37620,"endMs":50900,"text":"There were four walls, a floor and a roof, which made one room; and this room contained a rusty looking cooking stove, a cupboard for the dishes, a table, three or four chairs, and the beds.","translation":null,"reviewStatus":"needs_review"},{"id":"c0005","kind":"content","startMs":52200,"endMs":58480,"text":"Uncle Henry and Aunt Em had a big bed in one corner, and Dorothy a little bed in another corner.","translation":null,"reviewStatus":"needs_review"},{"id":"c0006","kind":"content","startMs":58960,"endMs":71200,"text":"There was no garret at all, and no cellar—except a small hole, dug in the ground, called a cyclone cellar, where the family could go in case one of those great whirlwinds arose, mighty enough to crush any building in its path.","translation":null,"reviewStatus":"needs_review"},{"id":"c0007","kind":"content","startMs":71700,"endMs":77500,"text":"It was reached by a trap-door in the middle of the floor, from which a ladder led down into the small, dark hole.","translation":null,"reviewStatus":"needs_review"},{"id":"c0008","kind":"content","startMs":78440,"endMs":84620,"text":"When Dorothy stood in the doorway and looked around, she could see nothing but the great gray prairie on every side.","translation":null,"reviewStatus":"needs_review"},{"id":"c0009","kind":"content","startMs":85060,"endMs":91560,"text":"Not a tree nor a house broke the broad sweep of flat country that reached the edge of the sky in all directions.","translation":null,"reviewStatus":"needs_review"},{"id":"c0010","kind":"content","startMs":92320,"endMs":97780,"text":"The sun had baked the plowed land into a gray mass, with little cracks running through it.","translation":null,"reviewStatus":"needs_review"},{"id":"c0011","kind":"content","startMs":98100,"endMs":105140,"text":"Even the grass was not green, for the sun had burned the tops of the long blades until they were the same gray color to be seen everywhere.","translation":null,"reviewStatus":"needs_review"},{"id":"c0012","kind":"content","startMs":105900,"endMs":113960,"text":"Once the house had been painted, but the sun blistered the paint and the rains washed it away, and now the house was as dull and gray as everything else.","translation":null,"reviewStatus":"needs_review"},{"id":"c0013","kind":"content","startMs":114520,"endMs":118000,"text":"When Aunt Em came there to live she was a young, pretty wife.","translation":null,"reviewStatus":"needs_review"},{"id":"c0014","kind":"content","startMs":118600,"endMs":120620,"text":"The sun and wind had changed her, too.","translation":null,"reviewStatus":"needs_review"},{"id":"c0015","kind":"content","startMs":121400,"endMs":129300,"text":"They had taken the sparkle from her eyes and left them a sober gray; they had taken the red from her cheeks and lips, and they were gray also.","translation":null,"reviewStatus":"needs_review"},{"id":"c0016","kind":"content","startMs":130060,"endMs":133000,"text":"She was thin and gaunt, and never smiled, now.","translation":null,"reviewStatus":"needs_review"},{"id":"c0017","kind":"content","startMs":133540,"endMs":149680,"text":"When Dorothy, who was an orphan, first came to her, Aunt Em had been so startled by the child's laughter that she would scream and press her hand upon her heart whenever Dorothy's merry voice reached her ears; and she still looked at the little girl with wonder that she could find anything to laugh at.","translation":null,"reviewStatus":"needs_review"},{"id":"c0018","kind":"content","startMs":150340,"endMs":151880,"text":"Uncle Henry never laughed.","translation":null,"reviewStatus":"needs_review"},{"id":"c0019","kind":"content","startMs":152260,"endMs":155960,"text":"He worked hard from morning till night and did not know what joy was.","translation":null,"reviewStatus":"needs_review"},{"id":"c0020","kind":"content","startMs":156440,"endMs":163280,"text":"He was gray also, from his long beard to his rough boots, and he looked stern and solemn, and rarely spoke.","translation":null,"reviewStatus":"needs_review"},{"id":"c0021","kind":"content","startMs":164100,"endMs":169060,"text":"It was Toto that made Dorothy laugh, and saved her from growing as gray as her other surroundings.","translation":null,"reviewStatus":"needs_review"},{"id":"c0022","kind":"content","startMs":169880,"endMs":178820,"text":"Toto was not gray; he was a little black dog, with long, silky hair and small black eyes that twinkled merrily on either side of his funny, wee nose.","translation":null,"reviewStatus":"needs_review"},{"id":"c0023","kind":"content","startMs":179660,"endMs":183560,"text":"Toto played all day long, and Dorothy played with him, and loved him dearly.","translation":null,"reviewStatus":"needs_review"},{"id":"c0024","kind":"content","startMs":185040,"endMs":186360,"text":"To-day, however, they were not playing.","translation":null,"reviewStatus":"needs_review"},{"id":"c0025","kind":"content","startMs":186680,"endMs":192280,"text":"Uncle Henry sat upon the door-step and looked anxiously at the sky, which was even grayer than usual.","translation":null,"reviewStatus":"needs_review"},{"id":"c0026","kind":"content","startMs":192940,"endMs":197360,"text":"Dorothy stood in the door with Toto in her arms, and looked at the sky too.","translation":null,"reviewStatus":"needs_review"},{"id":"c0027","kind":"content","startMs":198220,"endMs":199300,"text":"Aunt Em was washing the dishes.","translation":null,"reviewStatus":"needs_review"},{"id":"c0028","kind":"content","startMs":200940,"endMs":208440,"text":"From the far north they heard a low wail of the wind, and Uncle Henry and Dorothy could see where the long grass bowed in waves before the coming storm.","translation":null,"reviewStatus":"needs_review"},{"id":"c0029","kind":"content","startMs":209500,"endMs":217440,"text":"There now came a sharp whistling in the air from the south, and as they turned their eyes that way they saw ripples in the grass coming from that direction also.","translation":null,"reviewStatus":"needs_review"},{"id":"c0030","kind":"content","startMs":218380,"endMs":220660,"text":"Suddenly Uncle Henry stood up.","translation":null,"reviewStatus":"needs_review"},{"id":"c0031","kind":"content","startMs":220980,"endMs":228680,"text":"\"There's a cyclone coming, Em,\" he called to his wife; \"I'll go look after the stock.\" Then he ran toward the sheds where the cows and horses were kept.","translation":null,"reviewStatus":"needs_review"},{"id":"c0032","kind":"content","startMs":229900,"endMs":231460,"text":"Aunt Em dropped her work and came to the door.","translation":null,"reviewStatus":"needs_review"},{"id":"c0033","kind":"content","startMs":231820,"endMs":234400,"text":"One glance told her of the danger close at hand.","translation":null,"reviewStatus":"needs_review"},{"id":"c0034","kind":"content","startMs":235120,"endMs":237460,"text":"\"Quick, Dorothy!\" she screamed; \"run for the cellar!\"","translation":null,"reviewStatus":"needs_review"},{"id":"c0035","kind":"content","startMs":238440,"endMs":242720,"text":"Toto jumped out of Dorothy's arms and hid under the bed, and the girl started to get him.","translation":null,"reviewStatus":"needs_review"},{"id":"c0036","kind":"content","startMs":244140,"endMs":249040,"text":"Aunt Em, badly frightened, threw open the trap-door in the floor and climbed down the ladder into the small, dark hole.","translation":null,"reviewStatus":"needs_review"},{"id":"c0037","kind":"content","startMs":249620,"endMs":252460,"text":"Dorothy caught Toto at last, and started to follow her aunt.","translation":null,"reviewStatus":"needs_review"},{"id":"c0038","kind":"content","startMs":253160,"endMs":261340,"text":"When she was half way across the room there came a great shriek from the wind, and the house shook so hard that she lost her footing and sat down suddenly upon the floor.","translation":null,"reviewStatus":"needs_review"},{"id":"c0039","kind":"content","startMs":262760,"endMs":264000,"text":"A strange thing then happened.","translation":null,"reviewStatus":"needs_review"},{"id":"c0040","kind":"content","startMs":264500,"endMs":268120,"text":"The house whirled around two or three times and rose slowly through the air.","translation":null,"reviewStatus":"needs_review"},{"id":"c0041","kind":"content","startMs":268700,"endMs":270760,"text":"Dorothy felt as if she were going up in a balloon.","translation":null,"reviewStatus":"needs_review"},{"id":"c0042","kind":"content","startMs":271420,"endMs":275720,"text":"The north and south winds met where the house stood, and made it the exact center of the cyclone.","translation":null,"reviewStatus":"needs_review"},{"id":"c0043","kind":"content","startMs":276260,"endMs":292920,"text":"In the middle of a cyclone the air is generally still, but the great pressure of the wind on every side of the house raised it up higher and higher, until it was at the very top of the cyclone; and there it remained and was carried miles and miles away as easily as you could carry a feather.","translation":null,"reviewStatus":"needs_review"},{"id":"c0044","kind":"content","startMs":294220,"endMs":300120,"text":"It was very dark, and the wind howled horribly around her, but Dorothy found she was riding quite easily.","translation":null,"reviewStatus":"needs_review"},{"id":"c0045","kind":"content","startMs":300780,"endMs":309940,"text":"After the first few whirls around, and one other time when the house tipped badly, she felt as if she were being rocked gently, like a baby in a cradle.","translation":null,"reviewStatus":"needs_review"},{"id":"c0046","kind":"content","startMs":311160,"endMs":312520,"text":"Toto did not like it.","translation":null,"reviewStatus":"needs_review"},{"id":"c0047","kind":"content","startMs":312840,"endMs":319960,"text":"He ran about the room, now here, now there, barking loudly; but Dorothy sat quite still on the floor and waited to see what would happen.","translation":null,"reviewStatus":"needs_review"},{"id":"c0048","kind":"content","startMs":320880,"endMs":327940,"text":"Once Toto got too near the open trap-door, and fell in; and at first the little girl thought she had lost him.","translation":null,"reviewStatus":"needs_review"},{"id":"c0049","kind":"content","startMs":328280,"endMs":334960,"text":"But soon she saw one of his ears sticking up through the hole, for the strong pressure of the air was keeping him up so that he could not fall.","translation":null,"reviewStatus":"needs_review"},{"id":"c0050","kind":"content","startMs":335680,"endMs":344400,"text":"She crept to the hole, caught Toto by the ear, and dragged him into the room again; afterward closing the trap-door so that no more accidents could happen.","translation":null,"reviewStatus":"needs_review"},{"id":"c0051","kind":"content","startMs":344960,"endMs":354760,"text":"Hour after hour passed away, and slowly Dorothy got over her fright; but she felt quite lonely, and the wind shrieked so loudly all about her that she nearly became deaf.","translation":null,"reviewStatus":"needs_review"},{"id":"c0052","kind":"content","startMs":355320,"endMs":366760,"text":"At first she had wondered if she would be dashed to pieces when the house fell again; but as the hours passed and nothing terrible happened, she stopped worrying and resolved to wait calmly and see what the future would bring.","translation":null,"reviewStatus":"needs_review"},{"id":"c0053","kind":"content","startMs":367660,"endMs":375340,"text":"At last she crawled over the swaying floor to her bed, and lay down upon it; and Toto followed and lay down beside her.","translation":null,"reviewStatus":"needs_review"},{"id":"c0054","kind":"content","startMs":376080,"endMs":384100,"text":"In spite of the swaying of the house and the wailing of the wind, Dorothy soon closed her eyes and fell fast asleep.","translation":null,"reviewStatus":"needs_review"}]}
